function testEvent(action,d){testWallet=d;if(action==='test_claim'&&crystalPurchaseQuantity){var q=crystalPurchaseQuantity;crystalPurchaseQuantity=0;if(!E.d.onlineCrystal||d.owner!==E.d.onlineCrystal.owner){toast('กรุณาใช้บัญชีเดียวกับคลังผลึก');return;}if(E.d.gems<q*10||d.test_gems<q*10){toast('เพชรสำหรับแลกไม่พอ');return;}var beforeGems=E.d.gems;E.d.gems-=q*10;E.d.pendingTest={owner:d.owner,kind:'crystals',quantity:q,request_id:nonce160(),gemDebit:q*10,rateVersion:2};if(!E.save()){E.d.gems=beforeGems;delete E.d.pendingTest;toast('บันทึกไม่ได้ กรุณาลองอีกครั้ง');return;}Game.retryTest();return;}if(d.online)syncCrystal(d.online);var p=E.d.pendingTest,r=d.receipt;if((action==='test_exchange'||action==='test_cancel')&&p&&r&&r.id===p.request_id&&p.owner===d.owner){var before=JSON.stringify(E.d);E.d.testReceipts=E.d.testReceipts||[];if(!E.d.testReceipts.includes(r.id)){if(r.cancelled&&p.gemDebit)E.d.gems+=p.gemDebit;if(!r.cancelled&&(r.kind==='gold'||r.kind==='power')){E.d.testDelivery=E.d.testDelivery||{gold:0,power:0};E.d.testDelivery[r.kind]+=r.amount;E.d.testDelivery[r.kind]-=E.deposit(r.kind,E.d.testDelivery[r.kind]);}E.d.testReceipts.push(r.id);}delete E.d.pendingTest;if(!E.save()){E.d=JSON.parse(before);toast('บันทึกไม่ได้ รายการยังรอตรวจซ้ำ');}else toast(r.cancelled?'ยกเลิกรายการที่ยังไม่สำเร็จแล้ว':'แลกทรัพยากรสำเร็จ');}
 if(action==='test_targets'){testTarget=d.target;Game.practicePreview();return;}if(p&&p.gemDebit){Game.crystalExchange();hud();return;}testShop();hud();if(action==='test_claim')toast('ยืนยันรางวัลวันนี้แล้ว • เพชรคงเหลือ '+d.test_gems.toLocaleString()+' เม็ด');}
